import type {
  InputContextType,
  InputProps,
  InputPrefixProps,
  InputSuffixProps,
  InputCharCountProps,
  InputClearIconButtonProps,
} from "./input.types";

import React, { forwardRef, useRef, useState } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { useMergeRefs } from "@system";
import { IconButton } from "@components/icon-button";
import { Clear } from "@exp-textura/icons";

import { InputContext, useInput } from "./hooks/use-input";
import { useAriaDescribedBy } from "./hooks/use-aria-described-by";
import { useInputState } from "./hooks/use-input-state";
import { useInputMask } from "./hooks/use-input-mask";
import { InputClasses, StyledInput } from "./input.styles";

const defaultGetItemAriaLabel = (currentLength: number, maxLength: number): string =>
  `${currentLength} out of ${maxLength} characters used`;

const InputRoot = forwardRef<HTMLInputElement, InputProps>(({ styleSlots, ...props }, ref) => {
  const {
    className,
    variant = "default",
    inputSize = "default",
    placeholder,
    maxLength,
    mask,
    restrictCharacterCount,
    children,
    id,
    disabled,
    onFocus,
    onBlur,
    onMouseDown,
    onMouseUp,
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    defaultValue,
    ...rest
  } = props;
  const theme = useTheme();
  const {
    inputId: generatedInputId,
    currentValue,
    handleChange,
    clearValue,
    addAriaDescribedBy,
    removeAriaDescribedBy,
    getAriaDescribedBy,
  } = useInputState(props);
  const inputId = id || generatedInputId;
  const [isFocused, setIsFocused] = useState(false);
  const [isActive, setIsActive] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const mergedRefs = useMergeRefs(ref, inputRef);
  useInputMask(mask, inputRef);

  const contextValue: InputContextType = {
    inputId,
    inputRef,
    value: currentValue,
    inputSize,
    disabled,
    clearValue,
    maxLength,
    restrictCharacterCount,
    addAriaDescribedBy,
    removeAriaDescribedBy,
  };

  const charCountComponent = React.Children.toArray(children).find(
    (child) => (child as React.ReactElement).type === CharCount,
  );

  const otherChildren = React.Children.toArray(children).filter(
    (child) => (child as React.ReactElement).type !== CharCount,
  );

  return (
    <InputContext.Provider value={contextValue}>
      <StyledInput
        className={clsx(InputClasses.root, {
          [InputClasses.sm]: inputSize === "sm",
        })}
        currentTheme={theme}
        styleSlots={styleSlots}
        variant={variant}
      >
        <div
          className={InputClasses.inputWrapper}
          data-active={isActive}
          data-disabled={disabled}
          data-focus={isFocused}
        >
          <input
            {...rest}
            ref={mergedRefs}
            aria-describedby={getAriaDescribedBy}
            className={clsx(InputClasses.input, className)}
            disabled={disabled}
            id={inputId}
            maxLength={restrictCharacterCount ? maxLength : undefined}
            placeholder={placeholder}
            value={currentValue}
            onBlur={(e) => {
              setIsFocused(false);
              onBlur?.(e);
            }}
            onChange={handleChange}
            onFocus={(e) => {
              setIsFocused(true);
              onFocus?.(e);
            }}
            onMouseDown={(e) => {
              setIsActive(true);
              onMouseDown?.(e);
            }}
            onMouseUp={(e) => {
              setIsActive(false);
              onMouseUp?.(e);
            }}
          />
          {otherChildren}
        </div>
        {charCountComponent}
      </StyledInput>
    </InputContext.Provider>
  );
});
InputRoot.displayName = "Input";

const Prefix = forwardRef<HTMLDivElement, InputPrefixProps>(
  ({ children, className, "aria-hidden": ariaHidden, ...props }, ref) => {
    const { inputId } = useInput();
    const prefixId = `${inputId}-prefix`;
    useAriaDescribedBy({ id: prefixId, "aria-hidden": ariaHidden });

    return (
      <div ref={ref} className={clsx(InputClasses.prefix, className)} id={prefixId} {...props}>
        {children}
      </div>
    );
  },
);

Prefix.displayName = "Input.Prefix";

const Suffix = forwardRef<HTMLDivElement, InputSuffixProps>(
  ({ children, className, "aria-hidden": ariaHidden, ...props }, ref) => {
    const { inputId } = useInput();
    const suffixId = `${inputId}-suffix`;
    useAriaDescribedBy({ id: suffixId, "aria-hidden": ariaHidden });

    return (
      <div ref={ref} className={clsx(InputClasses.suffix, className)} id={suffixId} {...props}>
        {children}
      </div>
    );
  },
);
Suffix.displayName = "Input.Suffix";

const CharCount: React.FC<InputCharCountProps> = ({
  getItemAriaLabel: customGetItemAriaLabel,
  "aria-hidden": ariaHidden,
  render,
  ...props
}) => {
  const { value, maxLength, inputId } = useInput();
  const charCountId = `${inputId}-character-count`;
  const labelGetter = customGetItemAriaLabel || defaultGetItemAriaLabel;
  useAriaDescribedBy({ id: charCountId, "aria-hidden": ariaHidden });

  if (!maxLength) {
    return null;
  }

  const charCountProps = {
    "aria-label": labelGetter(value.length, maxLength),
    "aria-live": "polite" as const,
    className: clsx(InputClasses.characterCount, {
      [InputClasses.characterCountWarning]: value.length >= Number(maxLength),
    }),
    id: charCountId,
    ...props,
  };

  if (render) {
    const rendered = render(value.length, maxLength);
    if (React.isValidElement(rendered)) {
      return React.cloneElement(rendered as React.ReactElement, {
        ...charCountProps,
        className: clsx(charCountProps.className, rendered.props.className),
      });
    } else {
      throw new Error("Input.CharCount render prop must return a valid React element");
    }
  }

  return (
    <div {...charCountProps}>
      {value.length}/{maxLength}
    </div>
  );
};
CharCount.displayName = "Input.CharCount";

const InputClearIconButton: React.FC<InputClearIconButtonProps> = ({
  children,
  className,
  "aria-label": customAriaLabel,
  hideWhenEmpty = true,
  onClick,
  ...rest
}) => {
  const { value, disabled, inputRef, inputSize, clearValue } = useInput();

  if (!value && hideWhenEmpty) return null;

  const handleClear = (e: React.MouseEvent<HTMLButtonElement>) => {
    clearValue();
    onClick?.(e);
    queueMicrotask(() => {
      inputRef.current?.focus();
    });
  };

  return (
    <IconButton
      aria-label={customAriaLabel || "Clear"}
      buttonType="secondary"
      className={clsx(InputClasses.clearIconButton, className)}
      disabled={disabled}
      size={inputSize}
      onClick={(e: React.MouseEvent<HTMLButtonElement>) => {
        e.stopPropagation();
        e.preventDefault();
        handleClear(e);
      }}
      onPointerDown={(e) => e.preventDefault()}
      {...rest}
    >
      {children || <Clear />}
    </IconButton>
  );
};

InputClearIconButton.displayName = "Input.ClearIconButton";

const Input = Object.assign(InputRoot, {
  Prefix,
  Suffix,
  CharCount,
  ClearIconButton: InputClearIconButton,
});

export default Input;
